import{s as e}from"./i18n-BSBp_gjh.js";import{t}from"./buildPage-DWQZYYcs.js";var n=t({slug:`poshmark-audit`,heroTitle:e({defaultMessage:`Sell more on Poshmark in minutes`,id:`bebc224838`}),heroSubtitle:e({defaultMessage:`Perplexity Computer audits your closet, rewrites every listing, and builds a daily sharing schedule — automatically.`,id:`bc37c079d5`}),inputUrlCta:e({defaultMessage:`Audit my closet`,id:`ea9d8bd2f8`}),inputUrlPlaceholder:`poshmark.com/closet/...`,inputUrlPrefill:e({defaultMessage:`Go to {url} and run a full audit of this Poshmark closet. (1) Audit every listing for Poshmark search visibility — titles, descriptions, cover photos, category tags, brand tagging accuracy, and size/color attributes. (2) Rewrite underperforming titles and descriptions with high-search-volume keywords Poshmark buyers actually use and trending hashtags. (3) Pull recently sold comps for each item and suggest repricing based on actual sell-through rates and average sale price. (4) Flag stale listings over 60 days old that need relisting or a price drop to regain feed visibility. (5) Build a daily sharing and relisting schedule optimized for peak Poshmark traffic hours (7–9 AM, 12–1 PM, 7–10 PM ET). (6) Deliver a complete closet optimization report with rewritten listings, comp-based pricing recommendations, a 7-day sharing calendar, and a prioritized fix list.`,id:`398d4d8032`}),heroOverlaySteps:[e({defaultMessage:`Auditing every listing for titles, cover photos, tags, and search visibility`,id:`3d20bebf58`}),e({defaultMessage:`Pulling sold comps and calculating repricing recommendations for each item`,id:`16a4295223`}),e({defaultMessage:`Rewriting titles and descriptions with high-traffic Poshmark keywords`,id:`8fa1407885`}),e({defaultMessage:`Optimized listings, repricing recs, and 7-day sharing calendar — ready to publish`,id:`74f9d1a881`})],generatingSteps:[e({defaultMessage:`Visiting {url} to audit your closet listings, cover photos, and pricing`,id:`df2fea1398`}),e({defaultMessage:`Designing an agent to rewrite titles, descriptions, and tags for each listing`,id:`aebe8c238d`}),e({defaultMessage:`Configuring sold comp analysis and repricing recommendation pipelines`,id:`f27a1e475e`}),e({defaultMessage:`Setting up sharing schedule export and closet optimization report`,id:`0927f5d831`})],featureSectionTitle:e({defaultMessage:`From closet to sales`,id:`c59943efeb`}),featureCardTitles:[e({defaultMessage:`Connects to your reseller stack`,id:`6450aa2b0f`}),e({defaultMessage:`Listings ready to publish`,id:`599056f248`})],featureCardDescriptions:[e({defaultMessage:`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,id:`5012505887`}),e({defaultMessage:`Google Sheets, Canva, Notion, Airtable — Computer plugs into your tools so listings, pricing, and schedules stay organized in one workflow.`,id:`a7e69f586c`}),e({defaultMessage:`Rewritten titles. Keyword-rich descriptions. Comp-based repricing. 7-day sharing calendar. Computer delivers optimizations you can apply to your closet immediately.`,id:`03fcaf233e`})],capabilitySectionTitle:e({defaultMessage:`Your reseller assistant, on autopilot`,id:`5821ec95a1`}),capabilitySectionSubtitle:e({defaultMessage:`Paste your closet URL, get back optimized listings and a sharing schedule.`,id:`d1e2d83aba`}),capabilityCards:[{title:e({defaultMessage:`Listing SEO Audit`,id:`8d761298cd`}),description:e({defaultMessage:`Computer can audit every listing — titles, descriptions, cover photos, brand tags, and category accuracy — and flag what’s hurting your search rank.`,id:`717a5e60ba`})},{title:e({defaultMessage:`Comp-Based Repricing`,id:`4b68db69dc`}),description:e({defaultMessage:`Computer can pull recently sold comps for each item and recommend price adjustments based on actual sell-through rates and average sale price.`,id:`404a81733e`})},{title:e({defaultMessage:`Sharing & Relisting Schedule`,id:`e6e817f30b`}),description:e({defaultMessage:`Computer can build a daily sharing and relisting schedule timed to peak Poshmark traffic hours — so your listings stay at the top of search.`,id:`a24f51f043`})},{title:e({defaultMessage:`Connect Your Tools`,id:`2364841920`}),description:e({defaultMessage:`Computer can read from Google Sheets, Canva, Notion, and Airtable — build workflows to track inventory, create listing photos, and manage your closet.`,id:`3e9ffffaf4`})},{title:e({defaultMessage:`Knows Your Closet`,id:`f74b7a7aed`}),description:e({defaultMessage:`Computer can remember your brands, sizing, pricing strategy, and past sales across sessions — so every audit builds on what came before.`,id:`32fabeb348`})},{title:e({defaultMessage:`Stale Listing Alerts`,id:`18a293458d`}),description:e({defaultMessage:`Computer can watch your closet for listings losing visibility — and alert you when it’s time to relist, drop price, or reshare.`,id:`4d67783753`})}]});export{n as default};
